INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222201', 'Employment Law Essentials', 'Core U.S. federal employment laws every HR professional applies day to day.', 'A practical tour of the federal statutes behind most HR decisions: wage and hour rules, equal employment opportunity, protected leave, disability accommodation, and employment eligibility. Each lesson links to the primary agency guidance so you can return to the source when questions come up. State and local laws may be stricter — check with your legal partner.', 'Compliance', 'scale', 'published', 1) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222202', 'Harassment Prevention & Workplace Safety', 'Recognize, prevent, and respond to harassment and safety risks.', 'Covers what unlawful harassment looks like, how to build a reporting process people trust, and the employer responsibilities that keep the workplace physically safe. Required annually for all HR staff.', 'Compliance', 'shield', 'published', 2) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222203', 'Employee Relations & Investigations', 'Handle concerns fairly, document consistently, and close the loop.', 'A step-by-step approach to intake, investigation planning, interviewing, and documenting outcomes. Emphasizes neutrality, confidentiality, and retaliation prevention.', 'Employee Relations', 'handshake', 'published', 3) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222204', 'Inclusive Hiring Practices', 'Structure the hiring process to reduce bias and improve candidate experience.', 'From writing job descriptions to structured interviews and fair offer practices — tools to make every hiring decision more consistent, defensible, and inclusive.', 'Talent Acquisition', 'users', 'published', 4) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222205', 'Benefits & Total Rewards Basics', 'Explain benefits confidently and administer life events correctly.', 'Learn the moving parts of a typical benefits program — health plans, COBRA continuation, retirement plans, and leave — so you can answer employee questions accurately and know when to escalate.', 'Total Rewards', 'heart', 'published', 5) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222206', 'People Analytics Fundamentals', 'Turn HR data into decisions without compromising privacy.', 'Introduces the core workforce metrics (turnover, time to fill, engagement), how to present them clearly, and the privacy guardrails that apply to employee data.', 'People Analytics', 'chart', 'published', 6) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
INSERT INTO "courses" ("id", "title", "summary", "description", "category", "icon", "status", "sort_order") VALUES ('22222222-2222-4222-8222-222222222207', 'Manager Coaching Toolkit', 'Help managers run better 1:1s, feedback conversations, and reviews.', 'Work in progress — lessons are still being drafted by the People team.', 'Leadership', 'sparkles', 'draft', 7) ON CONFLICT ("id") DO NOTHING;--> statement-breakpoint
